// Shared policy, prepended to n8n node bodies by the workflow builder.
// Also importable by the dashboard validator and offline regression tests.
// This checks schema, citation availability and a conservative numeric lexicon;
// it does NOT prove that unrestricted prose follows logically from its evidence.
const MP_POLICY = (() => {
  const own = (o, k) => Object.prototype.hasOwnProperty.call(o, k);
  const record = o => o !== null && typeof o === 'object' && !Array.isArray(o);
  const exactKeys = (o, keys) => record(o) && Object.keys(o).length === keys.length && keys.every(k => own(o, k));
  const sentiments = ['Bullish', 'Cautiously Bullish', 'Neutral', 'Cautiously Bearish', 'Bearish'];
  const confidences = ['High', 'Medium', 'Low'];
  const directions = ['supports_bullish', 'supports_bearish', 'neutral'];
  const numericWords = /\b(?:zero|one|two|three|four|five|six|seven|eight|nine|ten|eleven|twelve|thirteen|fourteen|fifteen|sixteen|seventeen|eighteen|nineteen|twenty|thirty|forty|fifty|sixty|seventy|eighty|ninety|hundred|thousand|million|billion|trillion|quadrillion|half|halves|quarter|quarters|percent|percentage|first|second|third|fourth|fifth|sixth|seventh|eighth|ninth|tenth)\b/i;
  // Deliberately conservative: fixed instrument names containing digits and ordinary
  // uses of words such as "one" are withheld too. No claim of exhaustive language detection.
  const hasNumericText = text => typeof text !== 'string' || /\p{N}/u.test(text) || /\p{N}/u.test(text.normalize('NFKC')) || numericWords.test(text.normalize('NFKC'));
  const text = (v, max) => typeof v === 'string' && v.trim().length > 0 && v.length <= max && !/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/.test(v);
  const isUsableFact = (v, key) => {
    if (key === 'maSignal') return ['Golden Cross', 'Death Cross'].includes(v);
    if (typeof v === 'number') return Number.isFinite(v) && (key !== 'fearGreedValue' || (v >= 0 && v <= 100));
    if (typeof v !== 'string' || !v.trim() || v.length > 200) return false;
    // Match the complete fetched value, including the known GDP annotation.
    // Finding a numeric substring in malformed text is not usable source evidence.
    const match = /^(?:[$¥€£]|HK\$)?([+-]?(?:\d{1,3}(?:,\d{3})+|\d+)(?:\.\d+)?(?:[eE][+-]?\d+)?)(%)?(?: \((QoQ(?: annualized)?|YoY|annualized)\))?$/.exec(v.trim());
    if (!match || (match[3] && key !== 'gdpValue')) return false;
    const value = Number(match[1].replace(/,/g, ''));
    if (!Number.isFinite(value)) return false;
    return key !== 'fearGreedValue' || (/^\d+(?:\.\d+)?$/.test(v.trim()) && value >= 0 && value <= 100);
  };
  const isUsableHeadline = value => text(value, 2000);
  const keysByEdition = {
    US: ['buffettIndicator','shillerPE','yieldCurve','sp500VsMa200','maSignal','fearGreedValue','sp500','sp500Change','dowJones','dowJonesChange','vix','vixChange','gold','goldChange','oil','oilChange','dxy','dxyChange','btc','btcChange','gdpValue','cpiValue','unemploymentValue','fedRateValue','treasury10Y','treasury2Y'],
    CN: ['csi300','csi300Change','sseComposite','sseCompositeChange','szseComponent','szseComponentChange','hangSeng','hangSengChange','gold','goldChange','usdCny','usdCnyChange','gdpValue','cpiValue','unemploymentValue'],
  };
  const factKeysFor = edition => [...(keysByEdition[edition] || [])];
  const collectFacts = (data, edition) => {
    const keys = new Set(keysByEdition[edition] || []);
    for (const stock of (Array.isArray(data.stockDetails) ? data.stockDetails : [])) {
      if (!record(stock)) continue;
      const slug = String(stock.name || stock.symbol || '').toLowerCase().replace(/[^a-z0-9]/g, '');
      if (slug) keys.add(slug + 'Change');
    }
    const facts = {};
    for (const key of keys) if (own(data, key) && isUsableFact(data[key], key)) facts[key] = data[key];
    return facts;
  };
  const validateAnalysis = (candidate, { facts = {}, headlines = [] } = {}) => {
    const reasons = new Set();
    const fail = code => reasons.add(code);
    if (!exactKeys(candidate, ['sentiment','confidence','claims','interpretation','wisdom'])) {
      return {ok:false,reasonCodes:['ANALYSIS_SCHEMA_INVALID'],analysis:null};
    }
    if (!sentiments.includes(candidate.sentiment)) fail('SENTIMENT_INVALID');
    if (!confidences.includes(candidate.confidence)) fail('CONFIDENCE_INVALID');
    for (const [field,max] of [['sentiment',40],['confidence',10],['interpretation',1200],['wisdom',600]]) {
      if (!text(candidate[field], max)) fail('ANALYSIS_TEXT_INVALID');
      else if (hasNumericText(candidate[field])) fail('NUMERIC_MODEL_TEXT');
    }
    if (!Array.isArray(candidate.claims) || candidate.claims.length < 1 || candidate.claims.length > 6) fail('CLAIM_COUNT_INVALID');
    const claims = [];
    if (Array.isArray(candidate.claims) && candidate.claims.length <= 6) {
      for (const claim of candidate.claims) {
        if (!exactKeys(claim, ['claim','basedOn','direction'])) { fail('CLAIM_SCHEMA_INVALID'); continue; }
        if (!text(claim.claim, 600)) fail('CLAIM_TEXT_INVALID');
        else if (hasNumericText(claim.claim)) fail('NUMERIC_MODEL_TEXT');
        if (!directions.includes(claim.direction)) fail('DIRECTION_INVALID');
        if (!Array.isArray(claim.basedOn) || claim.basedOn.length < 1 || claim.basedOn.length > 12 || new Set(claim.basedOn).size !== claim.basedOn.length) {
          fail('CITATION_LIST_INVALID');
        } else {
          for (const key of claim.basedOn) {
            if (typeof key !== 'string' || !/^[A-Za-z][A-Za-z0-9_]{0,99}$/.test(key)) { fail('CITATION_KEY_INVALID'); continue; }
            const headline = /^headline_([1-9]\d*)$/.exec(key);
            if (headline) {
              const index = Number(headline[1]) - 1;
              if (!Number.isSafeInteger(index) || !isUsableHeadline(headlines[index])) fail('HEADLINE_UNAVAILABLE');
            } else if (!own(facts, key) || !isUsableFact(facts[key], key)) fail('FACT_UNAVAILABLE');
          }
        }
        claims.push({claim:typeof claim.claim === 'string' ? claim.claim.trim() : '',basedOn:Array.isArray(claim.basedOn) ? [...claim.basedOn] : [],direction:claim.direction});
      }
    }
    const bull = claims.filter(c => c.direction === 'supports_bullish').length;
    const bear = claims.filter(c => c.direction === 'supports_bearish').length;
    if (/Bullish/.test(candidate.sentiment) && !bull && bear) fail('DIRECTION_CONFLICT');
    if (/Bearish/.test(candidate.sentiment) && !bear && bull) fail('DIRECTION_CONFLICT');
    const reasonCodes = [...reasons];
    return {ok:!reasonCodes.length,reasonCodes,analysis:reasonCodes.length ? null : {
      sentiment:candidate.sentiment,confidence:candidate.confidence,claims,
      interpretation:candidate.interpretation.trim(),wisdom:candidate.wisdom.trim(),
    }};
  };
  const readApproval = (data, edition) => {
    try {
      const a = data.approvedAnalysis, v = data._verification;
      if (!record(data._health) || !['OK','DEGRADED'].includes(data._health.status)) return {ok:false,analysis:null,reasonCodes:['SOURCE_HEALTH_UNAVAILABLE']};
      if (!exactKeys(a, ['version','edition','analysis']) || a.version !== 1 || a.edition !== edition ||
          !record(v) || v.contractVersion !== 1 || v.status !== 'PASS' || v.action !== 'none' || v.edition !== edition ||
          !Array.isArray(v.reasonCodes) || v.reasonCodes.length) return {ok:false,analysis:null,reasonCodes:['APPROVAL_MISSING']};
      const result = validateAnalysis(a.analysis, {facts:collectFacts(data, edition),headlines:Array.isArray(data.headlinesList) ? data.headlinesList : []});
      if (result.ok && v.checked !== result.analysis.claims.length) return {ok:false,analysis:null,reasonCodes:['APPROVAL_COUNT_MISMATCH']};
      return result;
    } catch (_) { return {ok:false,analysis:null,reasonCodes:['APPROVAL_INVALID']}; }
  };
  const safeHttpUrl = value => {
    if (typeof value !== 'string' || !/^https?:\/\/[^\s<>"'\\]+$/i.test(value)) return null;
    // URL is not exposed by every n8n Code-node sandbox, so avoid depending on it.
    if (!/^https?:\/\/(?:[a-z0-9.-]+|\[[0-9a-f:]+\])(?::\d{1,5})?(?:[/?#]|$)/i.test(value)) return null;
    return value;
  };
  const verificationFor = (approval, data) => {
    const source = data._verification && Array.isArray(data._verification.reasonCodes) && data._verification.reasonCodes.length ? data._verification.reasonCodes : approval.reasonCodes;
    const reasonCodes = [...new Set((source || []).filter(c => typeof c === 'string' && /^[A-Z][A-Z0-9_]{0,79}$/.test(c)))];
    return {version:1,status:approval.ok ? 'approved' : 'withheld',checkedClaims:approval.ok ? approval.analysis.claims.length : 0,
      reasonCodes:approval.ok ? [] : reasonCodes.length ? reasonCodes : ['APPROVAL_INVALID']};
  };
  return {own,record,exactKeys,sentiments,confidences,directions,hasNumericText,isUsableFact,isUsableHeadline,factKeysFor,collectFacts,validateAnalysis,readApproval,safeHttpUrl,verificationFor};
})();
if (typeof module !== 'undefined' && module.exports) module.exports = MP_POLICY;

// Shared dashboard projection: edition selects source rows, never model behavior.
function MP_PREPARE(EDITION, {$input, $getWorkflowStaticData, Date: RuntimeDate, console}) {
  const items = $input.all();
  const d = {};
  for (const item of items) {
    const j = item.json || {};
    for (const key of Object.keys(j)) {
      if (j[key] !== undefined && j[key] !== null) d[key] = j[key];
    }
  }
  const safe = (value, fallback = 'N/A') =>
    (value === undefined || value === null || value === 'N/A' || value === '') ? fallback : value;
  const isUS = EDITION === 'US';
  const approval = MP_POLICY.readApproval(d, EDITION);
  const analysis = approval.ok ? approval.analysis : null;
  const health = d._health || null;
  const now = new RuntimeDate();
  const dateLabel = now.toLocaleDateString('en-US', {weekday:'long',year:'numeric',month:'long',day:'numeric'});

  const dashboard = {};
  if (isUS) {
    const cards = [
      ['buffettIndicator','Buffett Indicator','buffettStatus','buffettEmoji'],
      ['shillerPE','Shiller P/E (CAPE)','shillerStatus','shillerEmoji'],
      ['yieldCurve','Yield Curve (10Y-2Y)','yieldCurveStatus','yieldCurveEmoji'],
      ['sp500VsMa200','S&P 500 vs 200D-MA','sp500VsMa200Status','sp500VsMa200Emoji'],
    ];
    for (const [key,title,statusKey,emojiKey] of cards) {
      const trend = key === 'sp500VsMa200' && MP_POLICY.isUsableFact(d.maSignal, 'maSignal') ? ' (' + d.maSignal + ')' : '';
      dashboard[key] = {title,value:safe(d[key]),status:safe(d[statusKey],'') + trend,emoji:d[emojiKey] || ''};
    }
  }
  const fearGreed = isUS && MP_POLICY.isUsableFact(d.fearGreedValue, 'fearGreedValue') &&
    Number(d.fearGreedValue) >= 0 && Number(d.fearGreedValue) <= 100
    ? {score:Number(d.fearGreedValue),classification:d.fearGreedClassification || 'Unknown',change1d:d.fearGreedChange1d || '',change1w:d.fearGreedChange1w || ''}
    : null;
  const markets = isUS
    ? [['sp500','S&P 500'],['dowJones','Dow Jones'],['vix','VIX'],['gold','Gold'],['oil','Oil (WTI)'],['dxy','US Dollar'],['btc','Bitcoin']]
    : [['csi300','CSI 300'],['sseComposite','SSE Composite'],['szseComponent','SZSE Component'],['hangSeng','Hang Seng'],['gold','Gold'],['usdCny','USD/CNY']];
  const screener = markets.map(([key,label]) => ({
    label,factKey:key + 'Change',value:safe(d[key]),change:safe(d[key + 'Change'],''),
  }));
  const economicFields = [
    ['gdpValue','GDP Growth','gdpYear'],
    ['cpiValue','Inflation/CPI','cpiYear'],
    ['unemploymentValue','Unemployment','unemploymentYear'],
  ];
  if (isUS) economicFields.push(['fedRateValue','Fed Funds Rate'],['treasury10Y','10Y Treasury'],['treasury2Y','2Y Treasury']);
  const economic = economicFields.map(([key,label,periodKey]) => ({
    label,...(periodKey ? {period:d[periodKey] || ''} : {}),factKey:key,value:safe(d[key]),
  }));
  const claims = analysis && Array.isArray(analysis.claims)
    ? analysis.claims.map(claim => ({text:claim.claim,basedOn:claim.basedOn || [],direction:claim.direction || 'neutral'}))
    : [];

  // Read existing observations and scores without modifying ledger state.
  function buildHistory() {
    try {
      const state = $getWorkflowStaticData('global');
      const ledger = (state.mpLedger && state.mpLedger[EDITION]) || [];
      const scores = (state.mpTrackRecord && state.mpTrackRecord[EDITION]) || [];
      const scoredByPriorDate = {};
      for (const score of scores) scoredByPriorDate[score.priorDate] = score;
      return ledger.map(entry => {
        const scored = scoredByPriorDate[entry.date];
        return {date:entry.date,sentiment:entry.sentiment || 'n/a',verdict:entry.verdict || 'n/a',
          result:scored ? scored.result : null,actualChange:scored ? scored.actualChange : null};
      });
    } catch (_) { return []; }
  }
  const history = buildHistory();
  const facts = MP_POLICY.collectFacts(d, EDITION);
  const availableScreener = screener.filter(row => MP_POLICY.own(facts, row.factKey) && MP_POLICY.own(facts, row.factKey.replace(/Change$/, '')));
  if (Object.keys(facts).length === 0 || availableScreener.length === 0 || !health || !['OK','DEGRADED'].includes(health.status)) {
    console.error('[MarketPulse][PUBLISH-GUARD] dashboard publish SKIPPED (facts=' + Object.keys(facts).length + ', marketRows=' + availableScreener.length + ', health=' + (health ? health.status : 'none') + ') - retaining the last published payload without usable market quotes.');
    return [];
  }
  const payload = {
    schemaVersion:2,
    verification:MP_POLICY.verificationFor(approval, d),
    edition:EDITION,
    generatedAt:now.toISOString(),
    dateLabel,
    health:health ? {status:health.status,missing:health.missing || [],suspect:health.suspect || []} : {status:'OUTAGE',missing:['ALL'],suspect:[]},
    dashboard:Object.fromEntries(Object.entries(dashboard).filter(([key]) => MP_POLICY.own(facts, key))),
    facts,
    fearGreed,
    screener:availableScreener,
    economic:economic.filter(row => MP_POLICY.own(facts, row.factKey)),
    watchlist:d.watchlistSummary || '',
    trackRecord:{accuracy:d.trackRecordAccuracy || 'Building history',last:d.trackRecordLast || ''},
    history,
    analysisModel:analysis ? (d._analysisModel || null) : null,
    analysisProvider:analysis ? (d._analysisProvider || null) : null,
    analysis:analysis
      ? {sentiment:analysis.sentiment || 'n/a',confidence:analysis.confidence || 'n/a',claims,interpretation:analysis.interpretation || '',wisdom:analysis.wisdom || ''}
      : {sentiment:'Unavailable',confidence:'',claims:[],interpretation:'',wisdom:''},
    news:(Array.isArray(d.headlinesList) ? d.headlinesList : []).map((title,index) =>
      MP_POLICY.isUsableHeadline(title) ? {factKey:'headline_' + (index + 1),title,url:MP_POLICY.safeHttpUrl(Array.isArray(d.headlinesLinks) ? d.headlinesLinks[index] : null)} : null
    ).filter(Boolean),
    sources:isUS ? ['CNN Fear & Greed','FRED','MarketWatch','Yahoo Finance','multpl.com'] : ['Yahoo Finance','World Bank','Google News'],
  };
  return [{json:{dashboardJson:JSON.stringify(payload,null,2),commitMessage:'Publish ' + EDITION + ' dashboard data - ' + dateLabel}}];
}

// Edition-specific entry point; shared runtime is included by the builder.
const EDITION = 'CN';
return MP_PREPARE(EDITION, {$input, $getWorkflowStaticData, Date, console});

// ===== WEEKLY DEEP MVP (2026-07-22) =====
// Deterministic weekly wrap synthesized ONLY from the verdict ledger in staticData.
// No LLM call, no market fetch: every line below restates an already-verified,
// dated record. Fires Sunday 08:00 MYT: both markets have been closed since
// Saturday morning MYT, so the trading week is complete. Window = the 7 days
// ending Saturday, partitioning the calendar into clean Sun-Sat weeks.
const sd = $getWorkflowStaticData('global');
const ledger = sd.mpLedger || {};
const track = sd.mpTrackRecord || {};

// MYT is fixed UTC+8 (no DST) - shift the clock, then read the ISO date.
const MS_DAY = 24 * 3600 * 1000;
const mytNow = new Date(Date.now() + 8 * 3600 * 1000);
const iso = function (dt) { return dt.toISOString().slice(0, 10); };
// Window: the 7 days ENDING YESTERDAY (the completed week, Mon..Sun when fired Monday).
const endISO = iso(new Date(mytNow.getTime() - 1 * MS_DAY));
const startISO = iso(new Date(mytNow.getTime() - 7 * MS_DAY));

const esc = function (s) {
  return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
};
const sentIcon = function (s) {
  const t = String(s || '').toLowerCase();
  if (t.indexOf('bull') !== -1) return '🟢';
  if (t.indexOf('bear') !== -1) return '🔴';
  return '⚪';
};
const dayName = function (isoDate) {
  return ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'][new Date(isoDate + 'T00:00:00Z').getUTCDay()];
};
const fmtRange = function (a, b) {
  const M = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
  const da = new Date(a + 'T00:00:00Z'), db = new Date(b + 'T00:00:00Z');
  const left = M[da.getUTCMonth()] + ' ' + da.getUTCDate();
  const right = (da.getUTCMonth() === db.getUTCMonth() ? '' : M[db.getUTCMonth()] + ' ') + db.getUTCDate() + ', ' + db.getUTCFullYear();
  return left + '–' + right;
};

const inWindow = function (d) { return d && d >= startISO && d <= endISO; };

const sections = [];
const editions = [
  { key: 'US', flag: '🇺🇸', index: 'S&amp;P 500' },
  { key: 'CN', flag: '🇨🇳', index: 'CSI 300' },
];
for (const ed of editions) {
  const calls = (ledger[ed.key] || []).filter(function (e) { return inWindow(e.date); });
  const scored = (track[ed.key] || []).filter(function (t) { return inWindow(t.scoredDate); });
  const allTime = track[ed.key] || [];
  // Flats are excluded from both numerator and denominator - a day the market did not
  // move is not a missed call. Counting them as misses would understate the record as
  // badly as counting them as hits would flatter it.
  const allDecided = allTime.filter(function (t) { return t.result === 'hit' || t.result === 'miss'; });
  const allHits = allDecided.filter(function (t) { return t.result === 'hit'; }).length;
  const weekDecided = scored.filter(function (t) { return t.result === 'hit' || t.result === 'miss'; });
  const weekHits = weekDecided.filter(function (t) { return t.result === 'hit'; }).length;

  const lines = [];
  lines.push(ed.flag + ' <b>' + ed.key + ' edition</b>');
  if (calls.length === 0 && scored.length === 0) {
    lines.push('No digests were published this week.');
    sections.push(lines.join('\n'));
    continue;
  }
  if (calls.length > 0) {
    lines.push('<u>Calls made (' + calls.length + '):</u>');
    for (const c of calls) {
      const sTxt = c.sentiment ? esc(c.sentiment) : '<i>no verdict recorded</i>';
      lines.push(sentIcon(c.sentiment) + ' ' + dayName(c.date) + ' ' + c.date.slice(5) + ' — ' + sTxt + (c.model ? ' <i>(' + esc(c.model) + ')</i>' : ''));
    }
  }
  if (scored.length > 0) {
    lines.push('<u>Calls scored against ' + ed.index + ':</u>');
    for (const t of scored) {
      const mark = t.result === 'hit' ? '✅ hit' : t.result === 'flat' ? '⚪ too flat to judge' : '❌ miss';
      const gap = t.gapDays && t.gapDays > 1 ? ' (' + t.gapDays + '-day gap)' : '';
      lines.push(mark + ' — ' + dayName(t.priorDate) + ' ' + t.priorDate.slice(5) + ' called ' + esc(t.priorSentiment) + ', market moved ' + esc(t.actualChange) + gap);
    }
    // Denominators are the DECIDED counts, matching the numerators above. Using the raw
  // totals here would silently count every flat day as a miss.
  var flatWeek = scored.length - weekDecided.length;
  lines.push('Week: <b>' + weekHits + '/' + weekDecided.length + '</b> · All-time: <b>' + allHits + '/' + allDecided.length + '</b>'
    + (flatWeek ? ' · <i>' + flatWeek + ' day' + (flatWeek === 1 ? '' : 's') + ' too flat to judge</i>' : ''));
  } else {
    lines.push('No calls came due for scoring this week.');
  }
  sections.push(lines.join('\n'));
}

const message = [
  '📅 <b>MarketPulse Weekly — ' + fmtRange(startISO, endISO) + '</b>',
  '<i>Every line restates a dated, verified record from the public ledger — including the misses. Nothing is recalled from memory.</i>',
  sections.join('\n\n'),
  '📖 Daily digests, sources and the full track record:\nhttps://YOUR_GITHUB_USERNAME.github.io/MarketPulse/',
].join('\n\n');

return [{ json: { message: message } }];
